-- Every tenant-scoped domain table is default-deny without an explicit tenant context.
CREATE POLICY "organization_tenant_isolation" ON "Organization" USING ("tenantId" = NULLIF(current_setting('app.tenant_id', true),'')::uuid) WITH CHECK ("tenantId" = NULLIF(current_setting('app.tenant_id', true),'')::uuid);
